package dev.danielc.fujiapp;
import android.content.*;
import android.graphics.Bitmap;
import android.net.Uri;
import android.os.Build;
import android.provider.MediaStore;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Serial, journaled exports. Holds only application context and one photo at a time. */
final class FrameBatch {
 static final ExecutorService WORK=Executors.newSingleThreadExecutor();
 private static final Map<String,FrameBatch> LIVE=new HashMap<>();private static FrameBatch active;
 private final Context context;private final JSONObject record;private volatile boolean running,cancel;
 private FrameBatch(Context c,JSONObject r){context=c.getApplicationContext();record=r;}
 static synchronized FrameBatch open(Context c,JSONObject r){String id=r.optString("id");FrameBatch job=LIVE.get(id);if(job==null){job=new FrameBatch(c,r);LIVE.put(id,job);}return job;}
 static synchronized boolean busy(){return active!=null&&active.running;}
 static JSONObject create(List<Uri> uris,PhotoFrame.Options options,int quality,int titlePolicy)throws JSONException{
  if(uris.isEmpty()||uris.size()>30||PhotoFrame.requiredPhotos(options.style)>1)throw new IllegalArgumentException("请选择 1–30 张照片与单图模板");
  String id=UUID.randomUUID().toString();JSONObject r=new JSONObject();r.put("version",1);r.put("id",id);r.put("created",System.currentTimeMillis());r.put("options",FrameDrafts.snapshot(id,"","",options,Collections.emptyList(),quality));r.put("titlePolicy",titlePolicy);JSONArray items=new JSONArray();Set<String> seen=new HashSet<>();for(Uri uri:uris)if(seen.add(uri.toString())){JSONObject item=new JSONObject();item.put("source",uri.toString());item.put("state","pending");items.put(item);}r.put("items",items);return r;
 }
 private static File folder(Context c){return new File(c.getFilesDir(),"frame-batches");}
 private File file(){String id=record.optString("id");if(!id.matches("[a-zA-Z0-9-]{1,80}"))throw new IllegalArgumentException("Invalid batch ID");return new File(folder(context),id+".json");}
 synchronized void persist()throws IOException{File dir=folder(context);if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("无法保存任务记录");AtomicFile atomic=new AtomicFile(file());FileOutputStream out=null;try{out=atomic.startWrite();out.write(record.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));atomic.finishWrite(out);}catch(IOException e){if(out!=null)atomic.failWrite(out);throw e;}}
 static List<JSONObject> list(Context c){List<JSONObject> jobs=new ArrayList<>();File[] files=folder(c).listFiles();Set<File> unique=new HashSet<>();if(files!=null)for(File f:files)if(f.getName().endsWith(".json"))unique.add(f);else if(f.getName().endsWith(".json.bak"))unique.add(new File(folder(c),f.getName().substring(0,f.getName().length()-4)));for(File f:unique)try{JSONObject r=new JSONObject(new String(new AtomicFile(f).readFully(),java.nio.charset.StandardCharsets.UTF_8));if(r.optInt("version")==1&&r.optJSONArray("items")!=null&&r.optJSONArray("items").length()>0&&r.optJSONArray("items").length()<=30&&r.optJSONObject("options")!=null)jobs.add(r);}catch(Exception ignored){}Collections.sort(jobs,(a,b)->Long.compare(b.optLong("created"),a.optLong("created")));return jobs;}
 synchronized void prepareNames(){JSONArray items=record.optJSONArray("items");for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);Uri uri=Uri.parse(item.optString("source"));String name="file".equals(uri.getScheme())?new File(uri.getPath()).getName():"照片 "+(i+1);try(android.database.Cursor cursor=context.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst()&&!cursor.isNull(0))name=cursor.getString(0);}catch(RuntimeException ignored){}try{item.put("name",name);}catch(JSONException ignored){}}}
 synchronized String progress(){JSONArray a=record.optJSONArray("items");int done=0,failed=0;for(int i=0;i<a.length();i++){String s=a.optJSONObject(i).optString("state");if(s.equals("done"))done++;if(s.equals("failed"))failed++;}return (running?(cancel?"正在取消":"正在保存"):done==a.length()?"全部完成":done+failed==a.length()?"处理完成，有失败项":"任务待继续")+" · "+done+" / "+a.length()+" 张\n成功 "+done+" · 失败 "+failed+" · 未完成 "+(a.length()-done-failed)+(record.optString("error").isEmpty()?"":"\n"+record.optString("error"));}
 synchronized String details(){StringBuilder b=new StringBuilder();JSONArray a=record.optJSONArray("items");for(int i=0;i<a.length();i++){JSONObject item=a.optJSONObject(i);b.append(i+1).append(". ").append(item.optString("name","照片")).append(" · ").append(item.optString("state").equals("done")?"已保存":item.optString("state").equals("failed")?"失败 · "+item.optString("error"):"待保存").append('\n');}return b.toString();}
 synchronized boolean hasWork(boolean retry){JSONArray items=record.optJSONArray("items");for(int i=0;i<items.length();i++)if(shouldProcess(items.optJSONObject(i).optString("state"),retry))return true;return false;}
 boolean running(){return running;}
 void cancel(){cancel=true;}
 boolean start(boolean retry){synchronized(FrameBatch.class){if(busy())return false;running=true;cancel=false;active=this;}WORK.execute(()->run(retry));return true;}
 static boolean shouldProcess(String state,boolean retry){return state.equals(retry?"failed":"pending");}
 private void run(boolean retry){try{ synchronized(this){record.remove("error");persist();}JSONArray items=record.getJSONArray("items");PhotoFrame.Options options=new PhotoFrame.Options();JSONObject settings=record.getJSONObject("options");FrameDrafts.restore(settings,options);int quality=Math.max(0,Math.min(2,settings.optInt("quality",1)));for(int i=0;i<items.length()&&!cancel;i++){JSONObject item=items.getJSONObject(i);if(!shouldProcess(item.optString("state"),retry))continue;try{exportItem(item,i,options,quality,record.optInt("titlePolicy"));synchronized(this){item.put("state","done");item.remove("error");persist();}}catch(Exception|OutOfMemoryError e){synchronized(this){item.put("state","failed");item.put("error",e instanceof SecurityException?"原图授权失效，请重新选图创建任务":"读取或保存失败，请检查原图和存储空间");persist();}android.util.Log.w("frame-batch","Item failed",e);if(e instanceof OutOfMemoryError||new android.os.StatFs(context.getFilesDir().getAbsolutePath()).getAvailableBytes()<16L*1024*1024){cancel=true;}}}}
 catch(Exception e){synchronized(this){try{record.put("error","任务记录无法保存，已停止；请检查空间后重试");}catch(JSONException ignored){}}android.util.Log.w("frame-batch","Job stopped",e);}finally{running=false;synchronized(FrameBatch.class){if(active==this)active=null;}}}
 synchronized JSONObject snapshot(){try{return new JSONObject(record.toString());}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
 static List<Bitmap> previews(Context c,JSONObject record){List<Bitmap> results=new ArrayList<>();PhotoFrame.Options base=new PhotoFrame.Options();FrameDrafts.restore(record.optJSONObject("options"),base);JSONArray items=record.optJSONArray("items");for(int i=0;i<Math.min(3,items.length());i++){Bitmap source=null,frame=null;try{Uri uri=Uri.parse(items.optJSONObject(i).optString("source"));source=LocalMedia.decode(c,uri,180);if(source!=null){PhotoFrame.Options o=base.copy();int policy=record.optInt("titlePolicy");if(policy==0)o.title="";else if(policy==2)o.title=items.optJSONObject(i).optString("name","照片");PhotoDetails d;try{d=PhotoDetails.read(c,uri,"");}catch(Exception ignored){d=new PhotoDetails();}frame=PhotoFrame.render(source,d,o);int edge=Math.max(frame.getWidth(),frame.getHeight());if(edge>320){float scale=320f/edge;Bitmap small=Bitmap.createScaledBitmap(frame,Math.max(1,Math.round(frame.getWidth()*scale)),Math.max(1,Math.round(frame.getHeight()*scale)),true);if(small!=frame)frame.recycle();frame=small;}}}catch(Exception|OutOfMemoryError error){if(frame!=null){frame.recycle();frame=null;}}finally{if(source!=null)source.recycle();}results.add(frame);}return results;}
 private void exportItem(JSONObject item,int index,PhotoFrame.Options shared,int quality,int policy)throws Exception{
  String outputName="Fuji-frame-batch-"+record.getString("id")+"-"+index+".jpg";String existing=findPublished(outputName);if(existing!=null){synchronized(this){item.put("output",existing);}return;}
  Uri source=Uri.parse(item.getString("source"));String name="file".equals(source.getScheme())?new File(source.getPath()).getName():"照片.jpg";try(android.database.Cursor cursor=context.getContentResolver().query(source,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst()&&!cursor.isNull(0))name=cursor.getString(0);}catch(RuntimeException ignored){}synchronized(this){item.put("name",name);}
  PhotoFrame.Options o=shared.copy();if(policy==0)o.title="";else if(policy==2)o.title=name;
  int edge=new int[]{1080,2048,4096}[quality];Bitmap input=null,framed=null;File output=new File(new File(PhotoStorage.stagingRoot(context,false),"fudge"),outputName),partial=new File(context.getCacheDir(),outputName+".part");
  try{input=LocalMedia.decode(context,source,edge);if(input==null)throw new IOException("无法读取照片");int largest=Math.max(input.getWidth(),input.getHeight());if(largest>edge){float scale=(float)edge/largest;Bitmap scaled=Bitmap.createScaledBitmap(input,Math.max(1,Math.round(input.getWidth()*scale)),Math.max(1,Math.round(input.getHeight()*scale)),true);if(scaled!=input)input.recycle();input=scaled;}PhotoDetails d;try{d=PhotoDetails.read(context,source,name);}catch(IOException|RuntimeException unavailable){d=new PhotoDetails();}framed=PhotoFrame.render(input,d,o);try(OutputStream out=new FileOutputStream(partial)){if(!framed.compress(Bitmap.CompressFormat.JPEG,quality==0?85:95,out))throw new IOException("JPEG 编码失败");}if(!output.getParentFile().isDirectory()&&!output.getParentFile().mkdirs())throw new IOException("无法创建目录");try(InputStream in=new FileInputStream(partial);OutputStream out=new FileOutputStream(output)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);}String target=PhotoStorage.publish(context,output.getAbsolutePath(),false);synchronized(this){item.put("output",target);}if(Build.VERSION.SDK_INT>=29)output.delete();}
  finally{partial.delete();if(input!=null)input.recycle();if(framed!=null)framed.recycle();}
 }
 private String findPublished(String name){if(Build.VERSION.SDK_INT<29)return null;try(android.database.Cursor cursor=context.getContentResolver().query(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,new String[]{MediaStore.Images.Media._ID},MediaStore.MediaColumns.DISPLAY_NAME+"=? AND "+MediaStore.MediaColumns.RELATIVE_PATH+"=? AND "+MediaStore.MediaColumns.IS_PENDING+"=0",new String[]{name,"Pictures/Fudge/"},null)){if(cursor!=null&&cursor.moveToFirst())return ContentUris.withAppendedId(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,cursor.getLong(0)).toString();}catch(RuntimeException ignored){}return null;}
}
